// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }

    // fuzzed actor (potential caller) and recipient; the fuzzer will search for a non-owner actor
    function testFuzz_property(address caller, address recipient) public {
        // keep addresses broadly valid and non-zero
        vm.assume(caller != address(0));
        vm.assume(recipient != address(0));

        // Fund the contract so withdrawAll has balance to transfer
        uint256 initialBalance = 1 ether;
        vm.deal(address(c), initialBalance);

        // Ensure owner is address(this) as set in setUp(); the property: only owner can successfully call
        bool ok;

        // Make the call as `caller` sending no value (withdrawAll is non-payable call)
        vm.prank(caller);
        try c.withdrawAll(recipient) {
            ok = true;
        } catch {
            ok = false;
        }

        // The invariant: in the correct contract, withdrawAll only succeeds when caller == owner
        // So assert that success equals (caller == owner)
        // owner is address(this) because of setUp()
        assertTrue(ok == (caller == address(this)));
    }
}
